}

#[derive(Clone, Debug)]
pub enum Geo {
    Points(Vec<(f64, f64)>),
    Path(String),
}

impl Node {
    pub fn new(prim: Prim, chain: Vec<String>, span: Span) -> Node {
        Node {
            prim,
            chain,
            id: None,
            auto: false,
            classes: vec![],
            inline: vec![],
            text: None,
            children: vec![],
            parent: None,
            span,
