pub struct Parser<'a> {
    toks: &'a [Token],
    pos: usize,
    pub src: &'a str,
}

type PResult<T> = Result<T, Diag>;

fn perr(msg: &str, span: Span) -> Diag {
    Diag::error("parse", msg, span)
}

pub const SEP_ERR: &str = "expected a newline, ';', or a closing bracket";

impl<'a> Parser<'a> {
