    // ------------------------------------------------------------- statements
    fn parse_children(&mut self) -> PResult<Vec<Stmt>> {
        self.bump(); // [
        let mut out = Vec::new();
        loop {
            self.skip_seps();
            match self.peek() {
                Tok::RBrack => {
                    self.bump();
                    return Ok(out);
                }
                Tok::Eof => return Err(perr("expected ']'", self.span())),
                _ => {}
            }
            let s = self.parse_stmt(true)?;
            out.push(s);
            match self.peek() {
                Tok::Newline | Tok::Semi | Tok::RBrack => {}
                // several bare strings may share a line inside [ ]
                Tok::Str(_) if matches!(out.last(), Some(Stmt::Text(_))) => {}
                _ => return Err(perr(SEP_ERR, self.span())),
            }
        }
    }

    fn parse_stmt(&mut self, _in_children: bool) -> PResult<Stmt> {
        let start = self.span();
        match self.peek().clone() {
            Tok::Bar => {
                let node = self.parse_node()?;
                if matches!(self.peek(), Tok::LinkOp(_) | Tok::Amp | Tok::DimOp(_) | Tok::BarBar) {
                    return Err(perr(SEP_ERR, self.span()));
                }
                Ok(Stmt::Node(node))
            }
            Tok::Str(s) => {
                self.bump();
                let mut classes = Vec::new();
                while let Tok::Class(c) = self.peek().clone() {
                    self.bump();
                    classes.push(c);
                }
                let mut style = None;
                if matches!(self.peek(), Tok::LBrace) {
                    style = Some(self.parse_style_block()?.0);
                }
                Ok(Stmt::Text(TextStmt { text: s, classes, style, span: start.to(self.prev_span()) }))
            }
            Tok::Ident(_) => self.parse_link(),
            Tok::Var(_) => Err(perr("variables are declared in the stylesheet '{ }'", start)),
            _ => Err(perr("a node leads with bars — write '|box#X|' (a bare name is a link endpoint)", start)),
        }
    }

    fn parse_node(&mut self) -> PResult<NodeStmt> {
        let start = self.span();
        self.bump(); // |
        let mut type_name = None;
        let mut id = None;
        if let Tok::Ident(t) = self.peek().clone() {
            self.bump();
            type_name = Some(t);
        }
        if let Tok::Hash(h) = self.peek().clone() {
            self.bump();
            id = Some(h);
        }
        if !matches!(self.peek(), Tok::Bar) {
            if type_name.is_none() && id.is_none() {
                return Err(perr("'| |' needs a type or an '#id'", start));
            }
            return Err(perr("expected '|'", self.span()));
        }
        let bar = self.bump();
        if type_name.is_none() && id.is_none() {
            return Err(perr("'| |' needs a type or an '#id'", start));
        }
        let head_span = start.to(bar.span);
        let mut node = NodeStmt {
            type_name,
            id,
            label: None,
            classes: vec![],
            classes_span: None,
            style: None,
            style_span: None,
            children: None,
            span: head_span,
            head_span,
        };
        self.parse_node_tail(&mut node)?;
        node.span = start.to(self.prev_span());
        Ok(node)
    }

    fn parse_node_tail(&mut self, node: &mut NodeStmt) -> PResult<()> {
        if let Tok::Str(s) = self.peek().clone() {
            let t = self.bump();
            node.label = Some((s, t.span));
            if matches!(self.peek(), Tok::Str(_)) {
                return Err(perr("one inline label — put two or more in a '[ ]'", self.span()));
            }
        }
        if let Tok::Class(_) = self.peek() {
            let cs = self.span();
            while let Tok::Class(c) = self.peek().clone() {
                if self.tok().space_before && !node.classes.is_empty() {
                    return Err(perr("classes glue into a chain — write '.hot.loud', no space", self.span()));
                }
                self.bump();
                node.classes.push(c);
            }
            node.classes_span = Some(cs.to(self.prev_span()));
            if matches!(self.peek(), Tok::Str(_)) {
                return Err(perr("a label comes before classes — write '|box| \"X\" .hot'", self.span()));
            }
        }
        if matches!(self.peek(), Tok::LBrace) {
            let (d, sp) = self.parse_style_block()?;
            node.style = Some(d);
            node.style_span = Some(sp);
            if matches!(self.peek(), Tok::Str(_)) {
                return Err(perr("a label comes before classes — write '|box| \"X\" .hot'", self.span()));
            }
        }
        if matches!(self.peek(), Tok::LBrack) {
            node.children = Some(self.parse_children()?);
        }
        Ok(())
    }

    fn parse_path(&mut self) -> PResult<PathRef> {
        let start = self.span();
        let mut parts = Vec::new();
        match self.peek().clone() {
            Tok::Ident(n) => {
                self.bump();
                parts.push(n);
            }
            _ => return Err(perr("expected identifier", self.span())),
        }
        let mut index = None;
        loop {
            match self.peek().clone() {
                Tok::Dot => {
                    self.bump();
                    match self.peek().clone() {
                        Tok::Ident(n) => {
                            self.bump();
                            parts.push(n);
                        }
                        Tok::Num(v, _) => {
                            self.bump();
                            index = Some(v as u32);
                            break;
                        }
                        _ => return Err(perr("expected identifier", self.span())),
                    }
                }
                Tok::Num(v, s) if s.starts_with('.') && !self.tok().space_before => {
                    self.bump();
                    let digits = &s[1..];
                    index = Some(digits.parse::<u32>().unwrap_or(v as u32));
                    break;
                }
                _ => break,
            }
        }
        let mut anchor = None;
        if matches!(self.peek(), Tok::Colon) {
            self.bump();
            match self.peek().clone() {
                Tok::Ident(a) => {
                    self.bump();
                    anchor = Some(a);
                }
                _ => return Err(perr("expected identifier", self.span())),
            }
        }
        Ok(PathRef { parts, index, anchor, span: start.to(self.prev_span()) })
    }

    fn parse_endpoint(&mut self) -> PResult<Endpoint> {
        match self.peek().clone() {
            Tok::Ident(_) => Ok(Endpoint::Path(self.parse_path()?)),
            Tok::Bar => {
                let start = self.span();
                self.bump();
                let mut type_name = None;
                let mut id = None;
                if let Tok::Ident(t) = self.peek().clone() {
                    self.bump();
                    type_name = Some(t);
                }
                if let Tok::Hash(h) = self.peek().clone() {
                    self.bump();
                    id = Some(h);
                }
                if !matches!(self.peek(), Tok::Bar) {
                    if type_name.is_none() && id.is_none() {
                        return Err(perr("'| |' needs a type or an '#id'", start));
                    }
                    return Err(perr("expected '|'", self.span()));
                }
                let bar = self.bump();
                if type_name.is_none() && id.is_none() {
                    return Err(perr("'| |' needs a type or an '#id'", start));
                }
                let head_span = start.to(bar.span);
                Ok(Endpoint::Node(Box::new(NodeStmt {
                    type_name,
                    id,
                    label: None,
                    classes: vec![],
                    classes_span: None,
                    style: None,
                    style_span: None,
                    children: None,
                    span: head_span,
                    head_span,
                })))
            }
            Tok::Str(s) => {
                let t = self.bump();
                Ok(Endpoint::Text(s, t.span))
            }
            _ => Err(perr("expected identifier", self.span())),
        }
    }

    fn parse_fan(&mut self) -> PResult<Vec<Endpoint>> {
        let mut eps = vec![self.parse_endpoint()?];
        while matches!(self.peek(), Tok::Amp) {
            self.bump();
            eps.push(self.parse_endpoint()?);
        }
        Ok(eps)
    }

    fn parse_link(&mut self) -> PResult<Stmt> {
        let start = self.span();
        let first = self.parse_fan()?;
        let mut groups = vec![first];
        let mut ops = Vec::new();
        loop {
            match self.peek().clone() {
                Tok::LinkOp(op) | Tok::DimOp(op) => {
                    let t = self.bump();
                    ops.push((op, t.span));
                }
                Tok::BarBar => {
                    let t = self.bump();
                    ops.push(("||".to_string(), t.span));
                }
                _ => break,
            }
            // one-ended forms: 'a (o)' or 'a <- "text"'
            match self.peek() {
                Tok::Ident(_) | Tok::Bar => {
                    groups.push(self.parse_fan()?);
                }
                _ => break,
            }
        }
        if ops.is_empty() {
            // a bare endpoint, or something that looks like a declaration
            let had_colon = groups[0].iter().any(|e| matches!(e, Endpoint::Path(p) if p.anchor.is_some()));
            if had_colon || matches!(self.peek(), Tok::Colon) {
                return Err(Diag::error("declaration-outside-block", "a declaration belongs in a '{ }' block", start));
            }
            return Err(perr("a node leads with bars — write '|box#X|' (a bare name is a link endpoint)", start));
        }
        let mut link = LinkStmt {
            groups,
            ops,
            label: None,
            classes: vec![],
            style: None,
            labels: None,
            span: start,
        };
        if let Tok::Str(s) = self.peek().clone() {
            let t = self.bump();
            link.label = Some((s, t.span));
            if matches!(self.peek(), Tok::Str(_)) {
                return Err(perr("one inline label — put two or more in a '[ ]'", self.span()));
            }
        }
        while let Tok::Class(c) = self.peek().clone() {
            if self.tok().space_before && !link.classes.is_empty() {
                return Err(perr("classes glue into a chain — write '.hot.loud', no space", self.span()));
            }
            self.bump();
            link.classes.push(c);
        }
        if matches!(self.peek(), Tok::Str(_)) {
            return Err(perr("a label comes before classes — write '|box| \"X\" .hot'", self.span()));
        }
        if matches!(self.peek(), Tok::LBrace) {
            link.style = Some(self.parse_style_block()?.0);
            if matches!(self.peek(), Tok::Str(_)) {
                return Err(perr("a label comes before classes — write '|box| \"X\" .hot'", self.span()));
            }
        }
        if matches!(self.peek(), Tok::LBrack) {
            link.labels = Some(self.parse_children()?);
        }
        link.span = start.to(self.prev_span());
        Ok(Stmt::Link(link))
    }
}

pub fn parse(src: &str) -> Result<(Doc, Vec<crate::lexer::Comment>), Diag> {
    // the first syntax error exactly as the reference reports it (shared with fmt)
    crate::format::syntax_check(src)?;
    let lexed = crate::lexer::lex(src)?;
    let mut p = Parser::new(&lexed.tokens, src);
    let doc = p.parse_doc()?;
    Ok((doc, lexed.comments))
}

}

// skip a '( … )' group (the '(' already consumed); returns the end
// offset of the matching ')'
fn skip_group(&mut self, open: &Tok) -> R<usize> {
    let mut depth = 1usize;
    loop {
        match self.peek() {
            K::Eof => {
                return Err(perr("unterminated '(' group", open));
            }
            K::LParen => depth += 1,
            K::RParen => {
                depth -= 1;
                if depth == 0 {
                    return Ok(self.bump().e);
                }
            }
            _ => {}
        }
        self.bump();
    }
}

// call arguments after '(' : comma-separated groups of terms. Once an
// operator shows up, the rest of that group is kept verbatim; otherwise
// each term is rendered (a lone '( … )' group sheds its parens).
fn parse_call_args(&mut self, _open: &Tok) -> R<(Vec<String>, Option<f64>)> {
    let mut args: Vec<String> = Vec::new();
    // (rendered, start, end, is_group)
    let mut cur: Vec<(String, usize, usize, bool)> = Vec::new();
    let mut first_num: Option<f64> = None;
    loop {
        self.skip_newlines();
        if cur.is_empty() && self.arg_has_op() {
            // an operator anywhere in the argument: keep it verbatim
            let start = self.tok().s;
            let mut end = start;
            let mut depth = 0usize;
            loop {
                match self.peek() {
                    K::Eof => return Err(self.err_here("expected ')'")),
                    K::LParen => depth += 1,
                    K::RParen if depth == 0 => break,
                    K::RParen => depth -= 1,
                    K::Comma if depth == 0 => break,
                    K::Newline => {
                        self.bump();
                        continue;
                    }
                    _ => {}
                }
                end = self.bump().e;
            }
            if args.is_empty() {
                first_num = None;
            }
            args.push(self.src[start..end].to_string());
            if self.peek() == K::Comma {
                self.bump();
                continue;
            }
            self.bump(); // ')'
            return Ok((args, first_num));
        }
        let t = self.tok().clone();
        match t.k {
            K::RParen if !(cur.is_empty() && !args.is_empty()) => {
                self.bump();
                if !cur.is_empty() {
                    if args.is_empty() {
                        first_num = single_num(&cur, first_num);
                    }
                    args.push(self.finish_arg(&mut cur));
                }
                return Ok((args, first_num));
            }
            K::Comma if !cur.is_empty() => {
                self.bump();
                if args.is_empty() {
                    first_num = single_num(&cur, first_num);
                }
                args.push(self.finish_arg(&mut cur));
                continue;
            }
            K::Eof if !cur.is_empty() => return Err(self.err_here("expected ')'")),
            K::Colon => return Err(perr("a declaration ends with ';'", &t)),
            _ => {}
        }
        let s = t.s;
        let is_group = t.k == K::LParen;
        let term = self.parse_term()?;
        let e = self.last_end();
        if args.is_empty() && cur.is_empty() {
            first_num = term.num;
        }
        cur.push((term.text, s, e, is_group));
    }
}

// does the argument starting here hold an operator at its own level?
fn arg_has_op(&self) -> bool {
    let mut depth = 0usize;
    for t in &self.toks[self.pos..] {
        match t.k {
            K::Eof => return false,
            K::LParen => depth += 1,
            K::RParen if depth == 0 => return false,
            K::RParen => depth -= 1,
            K::Comma if depth == 0 => return false,
            K::Math | K::Eq if depth == 0 => return true,
            _ => {}
        }
    }
    false
}

fn finish_arg(&self, cur: &mut Vec<(String, usize, usize, bool)>) -> String {
    let out = if cur.len() == 1 && cur[0].3 {
        let (s, e) = (cur[0].1, cur[0].2);
        self.src[s + 1..e - 1].trim().to_string()
    } else {
        cur.iter().map(|x| x.0.clone()).collect::<Vec<_>>().join(" ")
    };
    cur.clear();
    out
}

// ----------------------------------------------------------- statements
// `anchor`: where leading trivia starts counting (the '[' itself unless an
// empty style block before it was dropped)
fn parse_children(&mut self, ctx: Ctx, anchor: Option<usize>) -> R<Block<Stmt>> {
    let open_idx = anchor.unwrap_or(self.pos);
    self.bump(); // [
    let mut items = Vec::new();
    loop {
        self.skip_newlines();
        match self.peek() {
            K::RBrack => break,
            K::Eof if ctx != Ctx::Labels => return Err(self.err_here("expected ']'")),
            _ => {}
        }
        let f = self.pos;
        self.brackets += 1;
        let st = self.parse_stmt(ctx);
        self.brackets -= 1;
        let st = st?;
        items.push((f, self.pos - 1, st));
        if ctx == Ctx::Labels {
            // labels and annotation nodes may share a line
            match self.peek() {
                K::Newline | K::RBrack | K::RBrace | K::Str | K::Bar => {}
                _ => return Err(self.err_here("a link's '[ ]' holds labels (text) and annotation nodes")),
            }
            continue;
        }
        self.after_stmt()?;
    }
    let close = self.pos;
    self.bump();
    Ok(self.build_block(Some(open_idx), items, close))
}

fn parse_stmt(&mut self, ctx: Ctx) -> R<Stmt> {
    match self.peek() {
        K::Bar => {
            let start = self.pos;
            let head = self.parse_node_head()?;
            if matches!(self.peek(), K::Link | K::Dim | K::Amp) || self.at_barbar() || self.capsule_path_ahead() {
                if ctx == Ctx::Labels {
                    return Err(self.err_here("a link's '[ ]' holds labels (text) and annotation nodes"));
                }
                self.pos = start;
                return self.parse_link();
            }
            let node = self.parse_node_tail(head)?;
            Ok(Stmt::Node(node))
        }
        K::Str => {
            let t = self.bump();
            let text = render_string(&t.text);
            let classes = self.parse_classes()?;
            let mut style = None;
            if self.peek() == K::LBrace {
                style = Some(self.parse_style_block()?);
                if self.peek() == K::Dot {
                    return Err(self.err_here(CLASS_FIRST));
                }
            }
            if self.peek() == K::LBrack {
                return Err(self.err_here(
                    "text content takes no '[ ]' — wrap it in '|block|' to give it children",
                ));
            }
            Ok(Stmt::Text(Text { text, classes, style: style.filter(|b| !b.entries.is_empty()) }))
        }
        K::Ident => {
            if ctx == Ctx::Labels {
                return Err(self.err_here("a link's '[ ]' holds labels (text) and annotation nodes"));
            }
            self.parse_link()
        }
        _ if ctx == Ctx::Labels => Err(self.err_here("a link's '[ ]' holds labels (text) and annotation nodes")),
        K::Var => Err(self.err_here("variables are declared in the stylesheet '{ }'")),
        _ => Err(self.err_here(NODE_ERR)),
    }
}

// '|type#id|' -> (rendered head, type name)
fn parse_node_head(&mut self) -> R<(String, Option<String>)> {
    if self.peek_at(1) == K::Link && self.tok_at(1).text == "-" {
        if self.peek_at(2) == K::Bar {
            return Err(self.err_here("a link is drawn by an operator — '|-|' only styles links (write 'a -> b')"));
        }
        return Err(perr("'| |' needs a type or an '#id'", self.tok_at(1)));
    }
    self.bump(); // |
    let mut ty = None;
    if self.peek() == K::Ident {
        ty = Some(self.bump().text);
        if self.peek() == K::DColon {
            return Err(self.err_here("a define belongs in the stylesheet"));
        }
    }
    let mut id = None;
