input.content:
// A structural reading of a document for `lini desugar`. It runs over the
// formatter's tokens after `format::syntax_check` accepted the file, so it
// does no error reporting of its own; declaration values come out in the
// formatter's canonical rendering (the desugared text prints through the same
// rules as `lini fmt`).

use crate::diag::Span;
use crate::format::expr;
use crate::format::lex::{Tok, K};
use crate::format::parse::{render_number, render_string};

#[derive(Clone, Debug, PartialEq)]
pub struct Decl {
    pub name: String, // with a leading '--' for variables
    pub groups: Vec<Vec<String>>,
}

impl Decl {
    pub fn new(name: &str, value: &str) -> Decl {
        Decl { name: name.to_string(), groups: vec![vec![value.to_string()]] }
    }
    pub fn groups(name: &str, groups: Vec<Vec<String>>) -> Decl {
        Decl { name: name.to_string(), groups }
    }
    pub fn value_text(&self) -> String {
        self.groups.iter().map(|g| g.join(" ")).collect::<Vec<_>>().join(", ")
    }
    pub fn text(&self) -> String {
        format!("{}: {};", self.name, self.value_text())
    }
    pub fn is_draw(&self) -> bool {
        self.name == "draw"
    }
    // the first term of the value, if any
    pub fn first(&self) -> Option<&str> {
        self.groups.first().and_then(|g| g.first()).map(|s| s.as_str())
    }
}

#[derive(Clone, Debug)]
pub enum Comp {
    Bars { ty: Option<String>, id: Option<String> },
    Class(String),
    Id(String),
    Dim(String),
}

#[derive(Clone, Debug)]
pub struct Rule {
    pub sel: Vec<(Comp, Span)>,
    pub decls: Vec<Decl>,
    pub span: Span,
}

#[derive(Clone, Debug)]
pub struct Define {
    pub name: String,
    pub base: String,
    pub decls: Vec<Decl>,
    pub body: Option<Vec<Stmt>>,
    pub span: Span,
    pub base_span: Span,
}

#[derive(Clone, Debug)]
pub enum SItem {
    Decl(Decl),
    Var(Decl),
    Binding(String),
    Rule(Rule),
    Define(Define),
}

#[derive(Clone, Debug)]
pub struct Node {
    pub ty: Option<String>,
    pub id: Option<String>,
    pub label: Option<String>, // decoded
    pub classes: Vec<String>,
    pub style: Vec<Decl>,
    pub children: Option<Vec<Stmt>>,
    pub span: Span,
    pub head_span: Span,
    pub ty_span: Span,
}

#[derive(Clone, Debug)]
pub struct Text {
    pub text: String, // decoded
    pub classes: Vec<String>,
    pub style: Vec<Decl>,
    pub span: Span,
}

#[derive(Clone, Debug)]
pub enum Endpoint {
    // a.b.2:anchor — `text` is the rendered path, `parts` the names
    Path { text: String, parts: Vec<String>, span: Span },
    // |type#id| optionally reaching inside: |g#x|.c:left
    Capsule { node: Node, tail: String },
    Text(String),
}

#[derive(Clone, Debug)]
pub struct Link {
    pub groups: Vec<Vec<Endpoint>>,
    pub ops: Vec<String>,
    pub label: Option<String>,
    pub classes: Vec<String>,
    pub style: Vec<Decl>,
    pub labels: Vec<Stmt>,
    pub span: Span,
}

#[derive(Clone, Debug)]
pub enum Stmt {
    Node(Node),
    Text(Text),
    Link(Link),
}

pub struct Doc {
    pub sheet: Vec<(SItem, Span)>,
    pub stmts: Vec<Stmt>,
}

pub struct P<'a> {
    src: &'a str,
    toks: &'a [Tok],
    pos: usize,
}

pub fn parse(src: &str) -> Result<Doc, crate::diag::Diag> {
    let lexed = crate::format::lex::lex(src)?;
    let mut p = P { src, toks: &lexed.toks, pos: 0 };
    Ok(p.doc())
}

impl<'a> P<'a> {
    fn peek(&self) -> K {
        self.toks[self.pos].k
    }
    fn peek_at(&self, k: usize) -> K {
        let i = (self.pos + k).min(self.toks.len() - 1);
        self.toks[i].k
    }
    fn tok(&self) -> &Tok {
        &self.toks[self.pos]
    }
    fn tok_at(&self, k: usize) -> &Tok {
        let i = (self.pos + k).min(self.toks.len() - 1);
        &self.toks[i]
    }
    fn bump(&mut self) -> Tok {
        let t = self.toks[self.pos].clone();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
    }
    fn last_end(&self) -> usize {
        if self.pos == 0 {
            0
        } else {
            self.toks[self.pos - 1].e
        }
    }
    fn skip_newlines(&mut self) {
        while self.peek() == K::Newline {
            self.bump();
        }
    }
    fn skip_seps(&mut self) {
        while matches!(self.peek(), K::Newline | K::Semi) {
            self.bump();
        }
    }
    fn at_barbar(&self) -> bool {
        self.peek() == K::Bar && self.peek_at(1) == K::Bar && !self.tok_at(1).sp
    }
    fn span_from(&self, s: usize) -> Span {
        Span::new(s, self.last_end().max(s))
    }

    fn doc(&mut self) -> Doc {
        self.skip_seps();
        let mut sheet = Vec::new();
        if self.peek() == K::LBrace {
            sheet = self.sheet();
        }
        let mut stmts = Vec::new();
        loop {
            self.skip_seps();
            if matches!(self.peek(), K::Eof | K::RBrack | K::RBrace) {
                break;
            }
            let before = self.pos;
            stmts.push(self.stmt());
            if self.pos == before {
                self.bump();
            }
        }
        Doc { sheet, stmts }
    }

    // ---------------------------------------------------------------- sheet
    fn sheet(&mut self) -> Vec<(SItem, Span)> {
        self.bump(); // {
        let mut items = Vec::new();
        loop {
            self.skip_seps();
            if matches!(self.peek(), K::RBrace | K::Eof) {
                self.bump();
                break;
            }
            let s = self.tok().s;
            let before = self.pos;
            if let Some(it) = self.sheet_item() {
                items.push((it, self.span_from(s)));
            }
            if self.pos == before {
                self.bump();
            }
        }
        items
    }

    fn sheet_item(&mut self) -> Option<SItem> {
        match self.peek() {
            K::Var => {
                let t = self.bump();
                self.bump(); // :
                let d = self.decl_rest(format!("--{}", t.text));
                Some(SItem::Var(d))
            }
            K::Ident => match self.peek_at(1) {
                K::Colon => Some(SItem::Decl(self.decl())),
                _ => Some(SItem::Binding(self.binding())),
            },
            K::Bar | K::Dot | K::Hash | K::Dim => Some(self.rule_or_define()),
            _ => None,
        }
    }

    fn binding(&mut self) -> String {
        let name = self.bump().text;
        let mut params: Option<Vec<String>> = None;
        if self.peek() == K::LParen {
            self.bump();
            let mut ps = Vec::new();
            loop {
                match self.peek() {
                    K::Ident => ps.push(self.bump().text),
                    K::Comma => {
                        self.bump();
                    }
                    K::RParen => {
                        self.bump();
                        break;
                    }
                    _ => break,
                }
            }
            params = Some(ps);
        }
        self.bump(); // =
        let rhs = if self.peek() == K::LParen {
            let open = self.bump();
            let close_end = self.skip_group();
            let inner = self.src[open.e..close_end.saturating_sub(1).max(open.e)].trim();
            expr::binding_group(inner)
        } else {
            let start = self.tok().s;
            let mut end = start;
            let mut depth = 0usize;
            loop {
                match self.peek() {
                    K::Semi | K::Eof => break,
                    K::Newline | K::RBrace if depth == 0 => break,
                    K::LParen => depth += 1,
                    K::RParen => depth = depth.saturating_sub(1),
                    _ => {}
                }
                end = self.bump().e;
            }
            expr::binding_bare(&self.src[start..end])
        };
        if self.peek() == K::Semi {
            self.bump();
        }
        let head = match params {
            Some(ps) if !ps.is_empty() => format!("{}({})", name, ps.join(", ")),
            _ => name,
        };
        format!("{} = {};", head, rhs)
    }

    fn rule_or_define(&mut self) -> SItem {
        let start = self.tok().s;
        if self.peek() == K::Bar && self.peek_at(1) == K::Ident && self.peek_at(2) == K::DColon {
            self.bump();
            let name = self.bump().text;
            self.bump(); // ::
            let bt = self.bump();
            let base = bt.text.clone();
            let base_span = Span::new(bt.s, bt.e);
            self.bump(); // |
            let mut decls = Vec::new();
            if self.peek() == K::LBrace {
                decls = self.style_block();
            }
            let mut body = None;
            if self.peek() == K::LBrack {
                body = Some(self.children(false));
            }
            return SItem::Define(Define { name, base, decls, body, span: self.span_from(start), base_span });
        }
        let mut sel = Vec::new();
        loop {
            let s = self.tok().s;
            match self.peek() {
                K::LBrace | K::Eof => break,
                K::Bar => {
                    self.bump();
                    let mut ty = None;
                    let mut id = None;
                    match self.peek() {
                        K::Ident => ty = Some(self.bump().text),
                        K::Link if self.tok().text == "-" => {
                            self.bump();
                            ty = Some("-".to_string());
                        }
                        _ => {}
                    }
                    if self.peek() == K::Hash {
                        id = Some(self.bump().text);
                    }
                    if self.peek() == K::Bar {
                        self.bump();
                    }
                    sel.push((Comp::Bars { ty, id }, self.span_from(s)));
                }
                K::Dot => {
                    self.bump();
                    let n = self.bump().text;
                    sel.push((Comp::Class(n), self.span_from(s)));
                }
                K::Hash => {
                    let h = self.bump();
                    sel.push((Comp::Id(h.text), self.span_from(s)));
                }
                K::Dim => {
                    let t = self.bump();
                    sel.push((Comp::Dim(t.text), self.span_from(s)));
                }
                _ => {
                    self.bump();
                }
            }
        }
        let decls = if self.peek() == K::LBrace { self.style_block() } else { Vec::new() };
        SItem::Rule(Rule { sel, decls, span: self.span_from(start) })
    }

    // ------------------------------------------------------- style blocks
    fn style_block(&mut self) -> Vec<Decl> {
        self.bump(); // {
        let mut out = Vec::new();
        loop {
            self.skip_seps();
            match self.peek() {
                K::RBrace => {
                    self.bump();
                    break;
                }
                K::Eof => break,
                K::Ident if self.peek_at(1) == K::Colon => out.push(self.decl()),
                _ => {
                    self.bump();
                }
            }
        }
        out
    }

    fn decl(&mut self) -> Decl {
        let t = self.bump();
        self.bump(); // :
        self.decl_rest(t.text)
    }

    fn decl_rest(&mut self, name: String) -> Decl {
        let draw = name == "draw";
        let groups = self.value(draw);
        if self.peek() == K::Semi {
            self.bump();
        }
        Decl { name, groups }
    }

    fn value(&mut self, draw: bool) -> Vec<Vec<String>> {
        let mut groups: Vec<Vec<String>> = vec![Vec::new()];
        let mut prev_call = false;
        loop {
            self.skip_newlines();
            match self.peek() {
                K::Semi | K::RBrace | K::RBrack | K::Eof => break,
                K::Comma => {
                    self.bump();
                    groups.push(Vec::new());
                    prev_call = false;
                    continue;
                }
                K::Colon => {
                    if draw && self.peek_at(1) == K::Ident && !self.tok_at(1).sp && prev_call && !self.tok().sp {
                        self.bump();
                        let tag = self.bump().text;
                        let g = groups.last_mut().unwrap();
                        if let Some(last) = g.pop() {
                            g.push(format!("{}:{}", last, tag));
                        }
                        prev_call = false;
                        continue;
                    }
                    break;
                }
                _ => {}
            }
            let before = self.pos;
            let (text, call) = self.term();
            if self.pos == before {
                break;
            }
            groups.last_mut().unwrap().push(text);
            prev_call = call;
        }
        groups
    }

    // one value term, rendered canonically -> (text, is a call)
    fn term(&mut self) -> (String, bool) {
        let t = self.tok().clone();
        match t.k {
            K::Num => {
                self.bump();
                (render_number(t.v), false)
            }
            K::Percent => {
                self.bump();
                (format!("{}%", render_number(t.v)), false)
            }
            K::Str => {
                self.bump();
                (render_string(&t.text), false)
            }
            K::Hash => {
                self.bump();
                (format!("#{}", t.text), false)
            }
            K::Var => {
                self.bump();
                (format!("--{}", t.text), false)
            }
            K::Ident => {
                self.bump();
                if self.peek() == K::LParen && !self.tok().sp {
                    self.bump();
                    let args = self.call_args();
                    return (format!("{}({})", t.text, args.join(", ")), true);
                }
                (t.text.clone(), false)
            }
            K::LParen => {
                let open = self.bump();
                let close_end = self.skip_group();
                let inner = self.src[open.e..close_end.saturating_sub(1).max(open.e)].trim();
                (format!("({})", inner), false)
            }
            _ => (String::new(), false),
        }
    }

    // after '(' : returns the end offset of the matching ')'
    fn skip_group(&mut self) -> usize {
        let mut depth = 1usize;
        loop {
            match self.peek() {
                K::Eof => return self.tok().e,
                K::LParen => depth += 1,
                K::RParen => {
                    depth -= 1;
                    if depth == 0 {
                        return self.bump().e;
                    }
                }
                _ => {}
            }
            self.bump();
        }
    }

    fn arg_has_op(&self) -> bool {
        let mut depth = 0usize;
        for t in &self.toks[self.pos..] {
            match t.k {
                K::Eof => return false,
                K::LParen => depth += 1,
                K::RParen if depth == 0 => return false,
                K::RParen => depth -= 1,
                K::Comma if depth == 0 => return false,
                K::Math | K::Eq if depth == 0 => return true,
                _ => {}
            }
        }
        false
    }

    fn call_args(&mut self) -> Vec<String> {
        let mut args: Vec<String> = Vec::new();
        // (rendered, start, end, is_group)
        let mut cur: Vec<(String, usize, usize, bool)> = Vec::new();
        loop {
            self.skip_newlines();
            if cur.is_empty() && self.arg_has_op() {
                let start = self.tok().s;
                let mut end = start;
                let mut depth = 0usize;
                loop {
                    match self.peek() {
                        K::Eof => break,
                        K::LParen => depth += 1,
                        K::RParen if depth == 0 => break,
                        K::RParen => depth -= 1,
                        K::Comma if depth == 0 => break,
                        K::Newline => {
                            self.bump();
                            continue;
                        }
                        _ => {}
                    }
                    end = self.bump().e;
                }
                args.push(self.src[start..end].to_string());
                if self.peek() == K::Comma {
                    self.bump();
                    continue;
                }
                self.bump(); // ')'
                return args;
            }
            let t = self.tok().clone();
            match t.k {
                K::RParen if !(cur.is_empty() && !args.is_empty()) => {
                    self.bump();
                    if !cur.is_empty() {
                        args.push(self.finish_arg(&mut cur));
                    }
                    return args;
                }
                K::Comma if !cur.is_empty() => {
                    self.bump();
                    args.push(self.finish_arg(&mut cur));
                    continue;
                }
                K::Eof => return args,
                _ => {}
            }
            let s = t.s;
            let is_group = t.k == K::LParen;
            let before = self.pos;
            let (text, _) = self.term();
            if self.pos == before {
                self.bump();
                continue;
            }
            let e = self.last_end();
            cur.push((text, s, e, is_group));
        }
    }

    fn finish_arg(&self, cur: &mut Vec<(String, usize, usize, bool)>) -> String {
        let out = if cur.len() == 1 && cur[0].3 {
            let (s, e) = (cur[0].1, cur[0].2);
            self.src[s + 1..e - 1].trim().to_string()
        } else {
            cur.iter().map(|x| x.0.clone()).collect::<Vec<_>>().join(" ")
        };
        cur.clear();
        out
    }

    // ----------------------------------------------------------- statements
    fn children(&mut self, labels: bool) -> Vec<Stmt> {
        self.bump(); // [
        let mut out = Vec::new();
        loop {
            self.skip_seps();
            match self.peek() {
                K::RBrack => {
                    self.bump();
                    break;
                }
                K::Eof => break,
                _ => {}
            }
            let before = self.pos;
            out.push(self.stmt());
            let _ = labels;
            if self.pos == before {
                self.bump();
            }
        }
        out
    }

    fn capsule_path_ahead(&self) -> bool {
        let t = self.toks;
        let mut j = self.pos;
        if !(matches!(t[j].k, K::Dot | K::Colon) && !t[j].sp) {
            return false;
        }
        while t[j].k == K::Dot {
            j += 1;
            if matches!(t[j].k, K::Ident | K::Num) {
                j += 1;
            } else {
                return false;
            }
        }
        if t[j].k == K::Colon {
            j += 1;
            if t[j].k != K::Ident {
                return false;
            }
            j += 1;
        }
        matches!(t[j].k, K::Link | K::Dim | K::Amp)
            || (t[j].k == K::Bar && t.get(j + 1).map_or(false, |n| n.k == K::Bar && !n.sp))
    }

    fn stmt(&mut self) -> Stmt {
        match self.peek() {
            K::Bar => {
                let start = self.pos;
                let _ = self.node_head();
                if matches!(self.peek(), K::Link | K::Dim | K::Amp) || self.at_barbar() || self.capsule_path_ahead() {
                    self.pos = start;
                    return self.link();
                }
                self.pos = start;
                Stmt::Node(self.node())
            }
            K::Str => {
                let t = self.bump();
                let classes = self.classes();
                let mut style = Vec::new();
                if self.peek() == K::LBrace {
                    style = self.style_block();
                }
                Stmt::Text(Text { text: t.text.clone(), classes, style, span: self.span_from(t.s) })
            }
            _ => self.link(),
        }
    }

    // '|type#id|' -> (type, id, type span)
    fn node_head(&mut self) -> (Option<String>, Option<String>, Span) {
        let s = self.tok().s;
        self.bump(); // |
        let mut ty = None;
        let mut ty_span = Span::new(s, s);
        if self.peek() == K::Ident {
            let t = self.bump();
            ty_span = Span::new(t.s, t.e);
            ty = Some(t.text);
        }
        let mut id = None;
        if self.peek() == K::Hash {
            id = Some(self.bump().text);
        }
        if self.peek() == K::Bar {
            self.bump();
        }
        (ty, id, ty_span)
    }

    fn classes(&mut self) -> Vec<String> {
        let mut out = Vec::new();
        while self.peek() == K::Dot && self.peek_at(1) == K::Ident {
            self.bump();
            out.push(self.bump().text);
        }
        out
    }

    fn node(&mut self) -> Node {
        let s = self.tok().s;
        let (ty, id, ty_span) = self.node_head();
        let head_span = self.span_from(s);
        let mut label = None;
        if self.peek() == K::Str {
            label = Some(self.bump().text);
        }
        let classes = self.classes();
        let mut style = Vec::new();
        if self.peek() == K::LBrace {
            style = self.style_block();
        }
        let mut children = None;
        if self.peek() == K::LBrack {
            children = Some(self.children(false));
        }
        Node { ty, id, label, classes, style, children, span: self.span_from(s), head_span, ty_span }
    }

    // the `.part.2:anchor` that may follow a name or a capsule
    fn path_tail(&mut self, s: &mut String, parts: &mut Vec<String>) {
        loop {
            if !(self.peek() == K::Dot && !self.tok().sp) {
                break;
            }
            if self.peek_at(1) == K::Ident && !self.tok_at(1).sp {
                self.bump();
                let n = self.bump().text;
                s.push('.');
                s.push_str(&n);
                parts.push(n);
                continue;
            }
            if self.peek_at(1) == K::Num && !self.tok_at(1).sp {
                self.bump();
                let n = self.bump();
                let digits: String = n.text.chars().filter(|c| c.is_ascii_digit()).collect();
                let idx = match digits.parse::<u64>() {
                    Ok(v) => v.to_string(),
                    Err(_) => digits,
                };
                s.push('.');
                s.push_str(&idx);
                break;
            }
            break;
        }
        if self.peek() == K::Colon && self.peek_at(1) == K::Ident {
            self.bump();
            s.push(':');
            s.push_str(&self.bump().text);
        }
    }

    fn endpoint(&mut self) -> Endpoint {
        match self.peek() {
            K::Ident => {
                let t = self.bump();
                let mut s = t.text.clone();
                let mut parts = vec![t.text.clone()];
                self.path_tail(&mut s, &mut parts);
                Endpoint::Path { text: s, parts, span: self.span_from(t.s) }
            }
            K::Bar => {
                let st = self.tok().s;
                let (ty, id, ty_span) = self.node_head();
                let head_span = self.span_from(st);
                let mut tail = String::new();
                let mut parts = Vec::new();
                self.path_tail(&mut tail, &mut parts);
                let node = Node {
                    ty,
                    id,
                    label: None,
                    classes: vec![],
                    style: vec![],
                    children: None,
                    span: head_span,
                    head_span,
                    ty_span,
                };
                Endpoint::Capsule { node, tail }
            }
            K::Str => {
                let t = self.bump();
                Endpoint::Text(t.text)
            }
            _ => {
                self.bump();
                Endpoint::Text(String::new())
            }
        }
    }

    fn fan(&mut self) -> Vec<Endpoint> {
        let mut eps = vec![self.endpoint()];
        while self.peek() == K::Amp {
            self.bump();
            eps.push(self.endpoint());
        }
        eps
    }

    fn link(&mut self) -> Stmt {
        let s = self.tok().s;
        let first = self.fan();
        let mut groups = vec![first];
        let mut ops = Vec::new();
        loop {
            let op = match self.peek() {
                K::Link | K::Dim => self.tok().text.clone(),
                K::Bar if self.at_barbar() => "||".to_string(),
                _ => break,
            };
            if op == "||" {
                self.bump();
            }
            self.bump();
            ops.push(op);
            match self.peek() {
                K::Ident | K::Bar => groups.push(self.fan()),
                K::Str => {
                    // one-ended: `a <- "text"` — the text is a label
                    break;
                }
                _ => break,
            }
        }
        let mut label = None;
        if self.peek() == K::Str {
            label = Some(self.bump().text);
        }
        let classes = self.classes();
        let mut style = Vec::new();
        if self.peek() == K::LBrace {
            style = self.style_block();
        }
        let mut labels = Vec::new();
        if self.peek() == K::LBrack {
            labels = self.children(true);
        }
        Stmt::Link(Link { groups, ops, label, classes, style, labels, span: self.span_from(s) })
    }
}

// The desugared document and its printer. The layout rules are the canonical
// ones of `lini fmt` (80 columns, 2-space indent, inline `{ }` / `[ ]` when
// they fit, aligned rows for bare cells, `draw:` subpaths on their own lines),
// except that a link's labels always stay in its `[ ]`.

use super::syntax::Decl;
use crate::format::parse::render_string;

pub const WIDTH: usize = 80;

#[derive(Clone, Debug)]
pub struct ONode {
    pub prim: String,
    pub id: Option<String>,
    pub label: Option<String>, // decoded; kept inline (lines, paths, images)
    pub classes: Vec<String>,  // without the dots
    pub decls: Vec<Decl>,
    pub children: Vec<Item>,
}

impl ONode {
    pub fn new(prim: &str) -> ONode {
        ONode { prim: prim.to_string(), id: None, label: None, classes: vec![], decls: vec![], children: vec![] }
    }
    pub fn decl(&self, name: &str) -> Option<&Decl> {
        self.decls.iter().rev().find(|d| d.name == name)
    }
    pub fn has_class(&self, c: &str) -> bool {
        self.classes.iter().any(|x| x == c)
    }
}

#[derive(Clone, Debug)]
pub struct OText {
    pub text: String, // decoded
    pub classes: Vec<String>,
    pub decls: Vec<Decl>,
}

#[derive(Clone, Debug)]
pub struct OLink {
    pub head: String,
    pub classes: Vec<String>,
    pub decls: Vec<Decl>,
    pub labels: Vec<Item>,
}

#[derive(Clone, Debug)]
pub enum Item {
    Node(ONode),
    Text(OText),
    Link(OLink),
}

impl Item {
    pub fn text(s: &str) -> Item {
        Item::Text(OText { text: s.to_string(), classes: vec![], decls: vec![] })
    }
}

pub enum SheetLine {
    Decls(Vec<Decl>),       // printed on one line
    Line(String),           // a variable or a binding
    Rule(String, Vec<Decl>), // selector { decls }
}

fn pad(n: usize) -> String {
    " ".repeat(n)
}

fn is_move(t: &str) -> bool {
    t.starts_with("move(") && t.ends_with(')')
}

fn classes_text(cs: &[String]) -> String {
    cs.iter().map(|c| format!(".{}", c)).collect::<String>()
}

// grid tracks a `columns:` value stands for (repeat(n, …) counts n)
fn tracks(d: &Decl) -> i64 {
    let mut n: i64 = 0;
    for t in d.groups.iter().flatten() {
        let mut k: i64 = 1;
        if let Some(rest) = t.strip_prefix("repeat(") {
            let first = rest.split(|c| c == ',' || c == ')').next().unwrap_or("").trim();
            if let Ok(v) = first.parse::<f64>() {
                if v.is_nan() || v < 1.0 {
                    k = 1;
                } else if v.is_infinite() || v > 1e15 {
                    k = 1_000_000_000_000_000;
                } else {
                    k = v.trunc() as i64;
                }
            }
        }
        n = n.saturating_add(k);
    }
    n
}

pub struct Printer {
    lines: Vec<String>,
}

impl Printer {
    pub fn new() -> Self {
        Printer { lines: Vec::new() }
    }

    pub fn finish(self) -> String {
        if self.lines.is_empty() {
            return String::new();
        }
        let mut s = self.lines.join("\n");
        s.push('\n');
        s
    }

    fn line(&mut self, indent: usize, text: &str) {
        self.lines.push(format!("{}{}", pad(indent), text));
    }

    pub fn doc(&mut self, sheet: &[SheetLine], items: &[Item]) {
        let mut sheet_printed = false;
        if !sheet.is_empty() {
            self.line(0, "{");
            for l in sheet {
                match l {
                    SheetLine::Decls(ds) => {
                        let mut run: Vec<String> = Vec::new();
                        for d in ds {
                            if d.is_draw() {
                                if !run.is_empty() {
                                    self.line(2, &run.join(" "));
                                    run.clear();
                                }
                                self.draw(2, d);
                            } else {
                                run.push(d.text());
                            }
                        }
                        if !run.is_empty() {
                            self.line(2, &run.join(" "));
                        }
                    }
                    SheetLine::Line(s) => self.line(2, s),
                    SheetLine::Rule(sel, ds) => {
                        if ds.is_empty() {
                            self.line(2, &format!("{} {{}}", sel));
                        } else {
                            self.composite(2, sel.clone(), ds, Kids::None);
                        }
                    }
                }
            }
            self.line(0, "}");
            sheet_printed = true;
        }
        let last_non_link = items.iter().rposition(|e| !matches!(e, Item::Link(_)));
        let first_link = items.iter().position(|e| matches!(e, Item::Link(_)));
        let link_break = match (last_non_link, first_link) {
            (Some(n), Some(l)) if l > n => Some(l),
            _ => None,
        };
        for (i, e) in items.iter().enumerate() {
            if (i == 0 && sheet_printed) || Some(i) == link_break {
                self.lines.push(String::new());
            }
            self.item(e, 0);
        }
    }

    fn draw(&mut self, indent: usize, d: &Decl) {
        let prefix = format!("{}: ", d.name);
        let col = indent + prefix.len();
        let pieces: Vec<&String> = d.groups.iter().flatten().collect();
        if pieces.is_empty() {
            self.line(indent, &format!("{} ;", prefix.trim_end()));
            return;
        }
        let mut cur = format!("{}{}{}", pad(indent), prefix, pieces[0]);
        for p in pieces.iter().skip(1) {
            if is_move(p) || cur.len() + 1 + p.len() + 1 > WIDTH {
                self.lines.push(cur);
                cur = format!("{}{}", pad(col), p);
            } else {
                cur.push(' ');
                cur.push_str(p);
            }
        }
        cur.push(';');
        self.lines.push(cur);
    }

    fn decls(&mut self, ds: &[Decl], indent: usize) {
        let mut run: Vec<String> = Vec::new();
        for d in ds {
            if d.is_draw() {
                if !run.is_empty() {
                    self.line(indent, &run.join(" "));
                    run.clear();
                }
                self.draw(indent, d);
            } else {
                run.push(d.text());
            }
        }
        if !run.is_empty() {
            self.line(indent, &run.join(" "));
        }
    }

    fn style_inline(ds: &[Decl]) -> Option<String> {
        if ds.iter().any(|d| d.is_draw() && d.groups.iter().flatten().filter(|t| is_move(t)).count() >= 2) {
            return None;
        }
        let parts: Vec<String> = ds.iter().map(|d| d.text()).collect();
        Some(format!("{{ {} }}", parts.join(" ")))
    }

    fn composite(&mut self, indent: usize, prefix: String, style: &[Decl], kids: Kids) {
        let mut cur = prefix;
        if !style.is_empty() {
            let inline = Self::style_inline(style).map(|s| format!("{} {}", cur, s));
            match inline {
                Some(l) if indent + l.len() <= WIDTH => cur = l,
                _ => {
                    self.line(indent, &format!("{} {{", cur));
                    self.decls(style, indent + 2);
                    cur = "}".to_string();
                }
            }
        }
        match kids {
            Kids::None => self.line(indent, &cur),
            Kids::Items(b, cols) => self.children(indent, cur, b, cols),
        }
    }

    fn children(&mut self, indent: usize, cur: String, b: &[Item], cols: Option<i64>) {
        let texts: Option<Vec<&OText>> = b
            .iter()
            .map(|e| match e {
                Item::Text(t) => Some(t),
                _ => None,
            })
            .collect();
        if let Some(texts) = texts {
            if let Some(n) = cols {
                self.line(indent, &format!("{} [", cur));
                self.rows(&texts, n, indent + 2);
                self.line(indent, "]");
                return;
            } else if texts.iter().all(|t| t.classes.is_empty() && t.decls.is_empty()) {
                let items: Vec<String> = texts.iter().map(|t| render_string(&t.text)).collect();
                let l = format!("{} [ {} ]", cur, items.join(" "));
                if indent + l.len() <= WIDTH {
                    self.line(indent, &l);
                    return;
                }
            }
        }
        self.line(indent, &format!("{} [", cur));
        for e in b {
            self.item(e, indent + 2);
        }
        self.line(indent, "]");
    }

    fn rows(&mut self, texts: &[&OText], n: i64, indent: usize) {
        let n = if n < 1 { 1 } else { n.min(1_000_000) as usize };
        let rendered: Vec<String> = texts.iter().map(|t| render_string(&t.text)).collect();
        let idx: Vec<usize> = (0..texts.len()).collect();
        let rows: Vec<&[usize]> = idx.chunks(n).collect();
        let lifted = |r: &[usize]| r.iter().any(|&i| !texts[i].classes.is_empty() || !texts[i].decls.is_empty());
        let mut widths = vec![0usize; n.min(texts.len().max(1))];
        for r in &rows {
            if lifted(r) {
                continue;
            }
            for (c, &i) in r.iter().enumerate() {
                widths[c] = widths[c].max(rendered[i].len());
            }
        }
        for r in &rows {
            if lifted(r) {
                let mut cur = String::new();
                for (c, &i) in r.iter().enumerate() {
                    let t = texts[i];
                    if c > 0 {
                        cur.push(' ');
                    }
                    cur.push_str(&rendered[i]);
                    if !t.classes.is_empty() {
                        cur.push(' ');
                        cur.push_str(&classes_text(&t.classes));
                    }
                    if !t.decls.is_empty() {
                        match Self::style_inline(&t.decls) {
                            Some(s) if indent + cur.len() + 1 + s.len() <= WIDTH => {
                                cur.push(' ');
                                cur.push_str(&s);
                            }
                            _ => {
                                self.line(indent, &format!("{} {{", cur));
                                self.decls(&t.decls, indent + 2);
                                cur = "}".to_string();
                            }
                        }
                    }
                }
                self.line(indent, &cur);
                continue;
            }
            let mut s = String::new();
            let last = r.len() - 1;
            for (c, &i) in r.iter().enumerate() {
                s.push_str(&rendered[i]);
                if c < last {
                    s.push_str(&pad(widths[c] - rendered[i].len() + 1));
                }
            }
            self.line(indent, &s);
        }
    }

    fn item(&mut self, s: &Item, indent: usize) {
        match s {
            Item::Node(n) => {
                let mut prefix = String::from("|");
                prefix.push_str(&n.prim);
                if let Some(id) = &n.id {
                    prefix.push('#');
                    prefix.push_str(id);
                }
                prefix.push('|');
                if let Some(l) = &n.label {
                    prefix.push(' ');
                    prefix.push_str(&render_string(l));
                }
                if !n.classes.is_empty() {
                    prefix.push(' ');
                    prefix.push_str(&classes_text(&n.classes));
                }
                let kids = if n.children.is_empty() {
                    Kids::None
                } else {
                    let cols = n.decl("columns").map(tracks);
                    Kids::Items(&n.children, cols)
                };
                self.composite(indent, prefix, &n.decls, kids);
            }
            Item::Text(t) => {
                let mut prefix = render_string(&t.text);
                if !t.classes.is_empty() {
                    prefix.push(' ');
                    prefix.push_str(&classes_text(&t.classes));
                }
                self.composite(indent, prefix, &t.decls, Kids::None);
            }
            Item::Link(l) => {
                let mut prefix = l.head.clone();
                if !l.classes.is_empty() {
                    prefix.push(' ');
                    prefix.push_str(&classes_text(&l.classes));
                }
                let kids = if l.labels.is_empty() { Kids::None } else { Kids::Items(&l.labels, None) };
                self.composite(indent, prefix, &l.decls, kids);
            }
        }
    }
}

enum Kids<'a> {
    None,
    Items(&'a [Item], Option<i64>),
}

