// Stylesheet rule order. Type rules use their type name as the slot; user
// defines and classes use "@define:NNNN" / "@class:NNNN".
pub static SLOT_ORDER: &[&str] = &[
    "canvas",
    "block", "oval", "hex", "slant", "cyl", "diamond", "poly", "path", "sketch", "line", "text", "icon", "image",
    "chart-text", "gutter",
    "box", "rect", "group", "row", "column", "grid", "caption", "footnote", "badge", "table", "cell", "header", "entity",
    "sign", "note", "topic", "mindmap", "chart", "bars", "area", "dots", "bubble", "band", "mark", "axis", "pie", "slice",
    "sequence", "loop", "alt", "opt", "else", "stack", "drawing", "floorplan", "hole", "hidden", "centerline",
    "pitch-circle", "plane", "magnifier", "feature-control", "datum", "surface-finish", "balloon", "page", "title-block",
    "frame", "zone", "tick", "field", "wall", "partition", "door", "window", "stairs", "bed", "sofa", "dining",
    "appliance", "bath", "schematic", "sch-line", "ref", "component", "pin", "space", "label",
    "@define",
    "link", "link-label", "cut-bg", "cut", "marker", "link-marker",
    "@class",
];

pub fn slot_rank(slot: &str) -> (usize, String) {
    if let Some(rest) = slot.strip_prefix("@define:") {
        let p = SLOT_ORDER.iter().position(|s| *s == "@define").unwrap();
        return (p, rest.to_string());
    }
    if let Some(rest) = slot.strip_prefix("@class:") {
        let p = SLOT_ORDER.iter().position(|s| *s == "@class").unwrap();
        return (p, rest.to_string());
    }
    match SLOT_ORDER.iter().position(|s| *s == slot) {
        Some(p) => (p, String::new()),
        None => (SLOT_ORDER.len(), slot.to_string()),
    }
}

// Diagnostics: errors and warnings with stable codes and source spans.

#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    pub fn new(start: usize, end: usize) -> Span {
        Span { start, end }
    }
    pub fn to(self, other: Span) -> Span {
        Span { start: self.start.min(other.start), end: self.end.max(other.end) }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Severity {
    Error,
    Warning,
}

#[derive(Debug, Clone)]
pub struct Diag {
    pub family: String,
    pub severity: Severity,
    pub message: String,
    pub span: Span,
    pub fixes: Vec<Fix>,
}

#[derive(Debug, Clone)]
pub struct Fix {
    pub message: String,
    pub span: Span,
    pub replacement: String,
}

