// a value written out in canonical text: groups split at top-level
// commas, terms at top-level spaces
pub fn val(name: &str, text: &str) -> Decl {
    let mut groups: Vec<Vec<String>> = vec![Vec::new()];
    let mut cur = String::new();
    let mut depth = 0i32;
    let mut quote = false;
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        if quote {
            cur.push(c);
            if c == '\\' {
                if let Some(n) = chars.next() {
                    cur.push(n);
                }
            } else if c == '"' {
                quote = false;
            }
            continue;
        }
        match c {
            '"' => {
                quote = true;
                cur.push(c);
            }
            '(' => {
                depth += 1;
                cur.push(c);
            }
            ')' => {
                depth -= 1;
                cur.push(c);
            }
            ',' if depth == 0 => {
                if !cur.is_empty() {
                    groups.last_mut().unwrap().push(std::mem::take(&mut cur));
                }
                groups.push(Vec::new());
                while chars.peek() == Some(&' ') {
                    chars.next();
                }
            }
            ' ' if depth == 0 => {
                if !cur.is_empty() {
                    groups.last_mut().unwrap().push(std::mem::take(&mut cur));
                }
            }
            c => cur.push(c),
        }
    }
    if !cur.is_empty() {
        groups.last_mut().unwrap().push(cur);
    }
    Decl { name: name.to_string(), groups }
}
// parse a rule's default text ("a: 1; b: 2 3;")
pub fn list(text: &str) -> Vec<Decl> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut quote = false;
    for c in text.chars() {
        if c == '"' {
            quote = !quote;
        }
        if c == ';' && !quote {
            let s = cur.trim().to_string();
            cur.clear();
            if let Some((n, v)) = s.split_once(':') {
                out.push(Decl::val(n.trim(), v.trim()));
            }
            continue;
        }
        cur.push(c);
    }
    out
}

