|floorplan#unit| "UNIT 12A — ONE BEDROOM · 65 m²" { unit: m; scale: 0.02; } [

  // ── The shell. One centreline loop; `close():west` mitres the seam like any
  // other corner, and every opening below cuts its own gap out of the poché.
  |wall#outer| {
    draw: move(0, 0) right(9.6):north down(6.8):east left(9.6):south
          close():west;
  } [
    |door#entry| "D1" { on: east; at: 1.2; width: 0.95; swing: right; }
    // hinged at the north jamb, opening into the flat — stationed clear of the
    // counter run that now turns the north-east corner
    |door#slider| "D2" { on: west; at: 3.4; width: 2.4; symbol: sliding; }
    // the balcony slider — two panels, no arc
    |window#w1| "W1" { on: west; at: 0.5; width: 2; }
    // the bedroom's own glazing onto the same balcony
  ]
  // North and south are **party walls** against the neighbouring units, so
  // they carry no openings at all — blank poché, the way a condo stacks. Every
  // opening a unit gets is on the entry side (east) or the balcony side (west).

  |partition#bedwall| { draw: move(0, 3.8) right(4.6):head down(3):side; } [
    |door#bed-door| "D3" { on: side; at: 0.4; width: 0.9; swing: right; }
    // 'right' of the pen's travel — the leaf opens into the bedroom
  ]
  |partition#laundry| { draw: move(6, 6.8) up(0.8); }
  // a stub off the south wall: with the bathroom's own west wall it makes the
  // 600 mm open-front alcove the stacked washer/dryer is built into
  |partition#bathwall| { draw: move(9.6, 4) left(2.9):head down(2.8):side; } [
    |door#bath-door| "D4" { on: side; at: 1; width: 0.8; hinge: end; }
    // hung on the far jamb, and 'swing:' left by default — into the bathroom
  ]

  // ── Casework: counters, the island, the wardrobe and the balcony deck.
  |slab#deck| { width: 1.4; height: 6.6; translate: -0.8 3.4; }
  // the balcony runs the west face between the two party walls — its ends stop
  // on their **inner** faces, so the deck is the unit's own and not a strip
  // shared with the neighbours
  |slab| { width: 3.9; height: 0.6; translate: 7.55 0.4; }
  // the kitchen run, against the north wall and into the north-east corner
  |slab| { width: 2; height: 0.9; translate: 7.2 2.05; radius: 4; }
  // the island — `radius:` is core, and sheet-space px: 4 is 50 mm at 1:50
  |slab| { width: 1.1; height: 0.55; translate: 2 1.75; }
  // the coffee table
  |slab| { width: 0.45; height: 0.45; translate: 0.6 4.075; }
  |slab| { width: 0.45; height: 0.45; translate: 3 4.075; }
  // a nightstand either side of the bed's head
  |slab| { width: 0.6; height: 1.4; translate: 4.25 6; }
  // the wardrobe
  |slab| { width: 1.2; height: 0.55; translate: 7.35 4.325; }
  // the vanity top

  // ── Fixtures. Each body masks what it overlaps, so the casework reads under
  // the appliances that sit in it; an `|appliance|`'s label centres **in** its
  // box (the F / DW / W/D convention), every other fixture's reads beside it.
  |appliance| { symbol: stove; translate: 6.4 0.4; }
  |appliance| "F" { symbol: fridge; translate: 8.1 0.4; }
  |appliance| "DW" { symbol: dishwasher; translate: 7.7 2.05; }
  |appliance| "W/D" { symbol: washer; translate: 6.35 6.4; }
  // seated in its alcove: flush on the bathroom wall, the south wall and the
  // stub, open to the hall
  |bath| { symbol: double-sink; translate: 6.8 2.05; }
  // the kitchen run's bowl — one unit, two basins
  |sofa| { symbol: stool; translate: 6.7 2.75; }
  |sofa| { symbol: stool; translate: 7.2 2.75; }
  |sofa| { symbol: stool; translate: 7.7 2.75; }
  // three ⌀350 stools pulled up to the island's open side
  |sofa| { translate: 2 0.55; }
  |dining| { symbol: four; translate: 4.3 2.2; }
  |bed| { translate: 1.8 4.85; }
  |bath| { symbol: sink; translate: 7.35 4.325; }
  |bath| { symbol: toilet; rotate: 180; translate: 9.15 5; }
  |bath| { symbol: tub; translate: 7.6 6.325; }
  |bath| { symbol: shower; translate: 9.05 6.25; }
  // free-standing in the other corner of the tub's own wall — a fixture has to
  // clear what it overlaps, never touch it

  // ── The sheet's own text: room names and authored areas [SPEC 15.11].
  |room| { translate: 2.2 2.75; } [ "LIVING / DINING" "23.9 m²" ]
  |room| { translate: 7.4 3.2; } [ "KITCHEN" ]
  |room| { translate: 3.3 6.1; } [ "BEDROOM" "12.8 m²" ]
  |room| { translate: 5.65 4.6; } [ "HALL" ]
  |room| { translate: 8.35 5.55; } [ "BATH" "7.3 m²" ]
  |room| { translate: -0.8 3.4; } [ "BALCONY" ]

  // The north arrow a plan needs is a `|sketch|` define — SPEC 24 reserves the
  // type, the pen already draws it. It rides the balcony's empty south end,
  // where sheet chrome costs the plan no margin and reads as no fixture.
  |sketch#north| {
    draw: move(-0.8, 5.73) line(0.22, 0.72) line(-0.22, -0.2) line(-0.22, 0.2)
          close();
    fill: --stroke-dark; stroke: none;
  }
  |room| { translate: -0.8 5.46; } [ "N" ]

  // ── Dimensions. Every named wall run answers three ways [SPEC 15.11]: the
  // bare `:segment` is the **centreline**, where a structural drawing measures,
  // and the derived `-in` / `-out` face anchors are its two offset faces — so
  // every dimension reads an **inside** face — a room its clear span, the
  // overalls the shell's clear interior: what a listing plan publishes. An
  // edge's extension line springs from the end nearest the dimension line
  // [SPEC 15.2], so every witness line here leaves a corner.
  outer:west-in (-) outer:east-in { side: top; }
  // → 9.4 — the interior overall, inner face to inner face
  outer:west-in (-) bedwall:side-out { side: bottom; }
  // → 4.45 — the bedroom's clear width ('side' runs south, so its 'out' face
  // is the western one, the bedroom's own)
  bedwall:side-in (-) outer:east-in { side: bottom; }
  // → 4.85 — hall and bath, clear to the east wall's inner face
  outer:north-in (-) bathwall:head-out { side: right; }
  // → 3.85 — kitchen and living, clear to the bathroom wall
  bathwall:head-in (-) outer:south-in { side: right; }
  // → 2.65 — the bathroom's clear depth
  outer:north-in (-) outer:south-in { side: right; }
  // → 6.6 — the interior overall, stacked outside the room clears
]
