import subprocess, re
def run(src):
    open('/tmp/desugar/ty.lini','w').write(src)
    r = subprocess.run(['/workspace/executable','desugar','ty.lini'],capture_output=True,cwd='/tmp/desugar')
    return r.stdout.decode(), r.stderr.decode()
variants = {'R':['plain','pot','ntc'],'C':['plain','polarized'],'L':['plain'],'D':['plain','zener','tvs','schottky'],'LED':['plain'],'Q':['npn','pnp','nfet','pfet'],'Y':['plain'],'F':['plain'],'FB':['plain'],'SW':['toggle','push'],'BT':['cell','battery'],'V':['dc','ac'],'I':['dc','ac'],'M':['plain'],'BZ':['plain'],'TP':['plain'],'opamp':['plain']}
rows = []
for t, vs in variants.items():
    for v in vs:
        sym = '' if t == 'opamp' else ' { symbol: %s; }' % v
        out, err = run('|schematic| [ |%s#x| "val"%s ]\n' % (t, sym))
        if err:
            print('ERR', t, v, err)
            continue
        line = re.search(r'\.lini-sch-line\.lini-path \{\s*path: "([^"]*)";', out)
        solid = re.search(r'\.lini-sch-solid\.lini-path \{\s*path: "([^"]*)"; pin: center;', out)
        pins = re.findall(r'\|block#(\w+)\| \.lini-block \{ pin: center; translate: (-?[\d.]+) (-?[\d.]+); \}', out)
        rows.append((t, v, line.group(1) if line else None, solid.group(1) if solid else None, pins))
def f(x):
    return x if '.' in x else x + '.0'
for r in rows:
    pins = ', '.join('("%s", %s, %s)' % (p[0], f(p[1]), f(p[2])) for p in r[4])
    solid = ('Some("%s")' % r[3]) if r[3] else 'None'
    print('    ("%s", "%s", "%s", %s, &[%s]),' % (r[0], r[1], r[2], solid, pins))

