import subprocess, os, glob, sys, tempfile, difflib, re
root = '/workspace/.claude/worktrees/agent-a16aa976db9486242/assets/'
files = sorted(glob.glob(root + 'test_doc_examples/*.lini') + glob.glob(root + 'test_samples/*.lini'))
mode = sys.argv[1] if len(sys.argv) > 1 else 'group'
show = int(sys.argv[2]) if len(sys.argv) > 2 else 3

def split_sheet(src):
    # find the stylesheet block at the top (balanced braces, ignoring strings/comments roughly)
    s = src
    i = 0
    n = len(s)
    # skip leading whitespace/comments
    while i < n:
        if s[i] in ' \t\r\n':
            i += 1
        elif s.startswith('//', i):
            while i < n and s[i] != '\n':
                i += 1
        else:
            break
    if i < n and s[i] == '{':
        depth = 0
        j = i
        instr = False
        while j < n:
            c = s[j]
            if instr:
                if c == '\\':
                    j += 2
                    continue
                if c == '"':
                    instr = False
            elif c == '"':
                instr = True
            elif s.startswith('//', j):
                while j < n and s[j] != '\n':
                    j += 1
                continue
            elif c == '{':
                depth += 1
            elif c == '}':
                depth -= 1
                if depth == 0:
                    return s[:j + 1], s[j + 1:]
            j += 1
    return '', s

ok = 0; bad = []
d = tempfile.mkdtemp(dir='/tmp/desugar')
for f in files:
    src = open(f).read()
    sheet, body = split_sheet(src)
    if mode == 'group':
        new = sheet + '\n|group#wrap| "W" [\n' + body + '\n]\n'
    elif mode == 'row':
        new = sheet + '\n|row| [\n' + body + '\n]\n'
    elif mode == 'box':
        new = sheet + '\n|box#bx| [\n' + body + '\n]\n'
    else:
        new = src
    p = os.path.join(d, 'v.lini')
    open(p, 'w').write(new)
    # assets referenced relatively: copy test_images if needed
    r1 = subprocess.run(['/workspace/executable', 'desugar', 'v.lini'], capture_output=True, cwd=d)
    r2 = subprocess.run(['/tmp/bin-desugar/executable', 'desugar', 'v.lini'], capture_output=True, cwd=d)
    if r1.stdout == r2.stdout and r1.stderr == r2.stderr and r1.returncode == r2.returncode:
        ok += 1
    else:
        o1 = (r1.stdout + r1.stderr).decode().split('\n'); o2 = (r2.stdout + r2.stderr).decode().split('\n')
        dl = list(difflib.unified_diff(o1, o2, 'orig', 'mine', lineterm='', n=1))
        bad.append((f, dl))
print('OK', ok, '/', len(files))
for f, dl in bad[:show]:
    print('#####', f)
    print('\n'.join(dl[2:30]))
print('FAILS:', ' '.join(os.path.basename(f) for f, _ in bad))

