    fn end_sym(&self, entry: &Term, via: usize) -> Option<Option<String>> {
        let mut cur = entry.clone();
        let mut skip = via;
        for _ in 0..64 {
            match &cur {
                Term::Pin(d, p) => {
                    let o = self.other_pin(d, p)?;
                    let exit = Term::Pin(d.clone(), o);
                    let (i, next) = self.at(&exit, None).into_iter().find(|(i, _)| *i != skip)?;
                    skip = i;
                    cur = next;
                }
                Term::Label(l) => return Some(self.syms.get(l).cloned().unwrap_or(None)),
                Term::Other(_) => return None,
            }
        }
        None
