    // down onto a ground, up into a supply, against a fixed pin's facing
    fn dest_dir(&self, entry: &Term, via: usize) -> Option<Dir> {
        let mut cur = entry.clone();
        let mut skip = via;
        let mut first = true;
        for _ in 0..64 {
            match &cur {
                Term::Pin(d, p) => {
                    if !first && (self.anchor(d) || self.fixed(d) || !self.two_pin(d)) {
                        return self.pin_dir(d, p).map(|f| f.opposite());
                    }
                    first = false;
                    let o = self.other_pin(d, p)?;
                    let exit = Term::Pin(d.clone(), o);
                    let (i, next) = self.at(&exit, None).into_iter().find(|(i, _)| *i != skip)?;
                    skip = i;
                    cur = next;
                }
                Term::Label(l) => {
                    let s = self.syms.get(l).cloned().unwrap_or(None);
                    return if gnd_like(&s) {
                        Some(Dir::D)
                    } else if power_like(&s) {
                        Some(Dir::U)
                    } else {
                        None
                    };
                }
                Term::Other(_) => return None,
            }
        }
        None
    }""")
