import subprocess, os, random, difflib, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
n = int(sys.argv[2]) if len(sys.argv) > 2 else 200
show = int(sys.argv[3]) if len(sys.argv) > 3 else 3
rnd = random.Random(seed)
d = '/tmp/desugar/genfuzz'
os.makedirs(d, exist_ok=True)
TYPES = ['box', 'box', 'box', 'group', 'row', 'column', 'oval', 'cyl', 'hex', 'rect', 'block', 'table', 'entity', 'note', 'badge', 'caption', 'icon', 'line', 'grid', 'chart', 'sketch', 'drawing', 'stack', 'page', 'title-block', 'mindmap']
ids = []
def label():
    return rnd.choice(['"A"', '"Hello world"', '"x y"', '""', '"multi\\nline"', '"q\\"t"', '"star"'])
def style():
    opts = ['fill: red;', 'stroke: blue;', 'gap: 5;', 'padding: 3 4;', 'width: 40;', 'columns: repeat(2);', 'direction: row;', 'align: start;', 'title: "T";', 'unit: cm;', 'sheet: a5;', 'revolve: x-axis;', 'draw: move(0, 0) right(4);']
    k = rnd.randint(0, 3)
    if k == 0:
        return ''
    return ' { ' + ' '.join(rnd.sample(opts, k)) + ' }'
def node(depth, defines):
    t = rnd.choice(TYPES + defines)
    s = '|%s' % t
    if rnd.random() < 0.5:
        i = 'n%d' % len(ids)
        ids.append(i)
        s += '#' + i
    s += '|'
    if rnd.random() < 0.7:
        s += ' ' + label()
    if rnd.random() < 0.2:
        s += ' .k'
    s += style()
    if depth < 3 and rnd.random() < 0.4:
        kids = [stmt(depth + 1, defines) for _ in range(rnd.randint(0, 3))]
        s += ' [\n' + '\n'.join(kids) + '\n]'
    return s
def link():
    a = rnd.choice(ids + ['x', 'y', 'z']) if ids else rnd.choice(['x', 'y'])
    b = rnd.choice(ids + ['x', 'w', 'z']) if ids else rnd.choice(['z', 'w'])
    op = rnd.choice(['->', '--', '<->', '-->', '~>', '-o<'])
    s = '%s %s %s' % (a, op, b)
    if rnd.random() < 0.3:
        s += ' %s %s' % (op, rnd.choice(['x', 'q']))
    if rnd.random() < 0.4:
        s += ' ' + rnd.choice(['"lbl"', '"two words"'])
    if rnd.random() < 0.2:
        s += ' .k'
    if rnd.random() < 0.2:
        s += ' { stroke: red; }'
    if rnd.random() < 0.15:
        s += ' [ "m1" "m2" ]'
    return s
def stmt(depth, defines):
    r = rnd.random()
    if r < 0.6:
        return node(depth, defines)
    if r < 0.8:
        return link()
    return rnd.choice(['"text"', '"styled" { font-size: 20; }', '"cls" .k'])
def gen():
    ids.clear()
    sheet = []
    defines = []
    if rnd.random() < 0.5:
        sheet.append(rnd.choice(['layout: grid;', 'gap: 20;', 'padding: 5;', 'direction: column;', 'layout: drawing;', 'layout: sequence;', 'font-size: 12;']))
    sheet.append('.k { fill: red; }')
    for i in range(rnd.randint(0, 2)):
        base = rnd.choice(['box', 'group', 'table', 'row', 'oval', 'drawing'])
        nm = 'd%d' % i
        body = ''
        if rnd.random() < 0.5:
            body = ' [ ' + rnd.choice(['"body"', '|box| "b"', '|badge| "bd"', 'p -> q']) + ' ]'
        sheet.append('|%s::%s| { stroke: green; }%s' % (nm, base, body))
        defines.append(nm)
    if rnd.random() < 0.3:
        sheet.append('|box| { radius: 2; }')
    if rnd.random() < 0.3:
        sheet.append('|-| { stroke: gray; }')
    src = '{\n  ' + '\n  '.join(sheet) + '\n}\n'
    for _ in range(rnd.randint(1, 6)):
        src += stmt(0, defines) + '\n'
    return src
ok = 0; bad = []
for i in range(n):
    src = gen()
    p = os.path.join(d, 'g.lini')
    open(p, 'w').write(src)
    r1 = subprocess.run(['/workspace/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    r2 = subprocess.run(['/tmp/bin-desugar/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    if (r1.stdout, r1.stderr, r1.returncode) == (r2.stdout, r2.stderr, r2.returncode):
        ok += 1
    else:
        o1 = (r1.stdout + r1.stderr).decode().split('\n'); o2 = (r2.stdout + r2.stderr).decode().split('\n')
        dl = list(difflib.unified_diff(o1, o2, 'orig', 'mine', lineterm='', n=1))
        bad.append((src, dl, r1.returncode))
print('OK', ok, '/', n, ' (orig errors among fails: %d)' % sum(1 for b in bad if b[2] != 0))
for src, dl, rc in bad[:show]:
    print('=' * 30)
    print(src)
    print('\n'.join(dl[2:30]))

