d = '/tmp/desugar/drawfuzz'
os.makedirs(d, exist_ok=True)

def draw():
    segs = []
    for _ in range(rnd.randint(1, 3)):
        seg = 'move(%d, %d)' % (rnd.randint(-20, 20), rnd.randint(-20, 20))
        for _ in range(rnd.randint(1, 4)):
            seg += ' ' + rnd.choice(['up(5)', 'right(10)', 'down(3)', 'left(4)', 'fillet(2)', 'chamfer(1)', 'right(8):a', 'circle(4)'])
        if rnd.random() < 0.4:
            seg += ' close()'
        segs.append(seg)
    return ' '.join(segs)

def part(depth, ids):
    t = rnd.choice(['sketch', 'sketch', 'hidden', 'hole', 'rect', 'oval', 'plane', 'magnifier', 'centerline', 'box', 'note', 'balloon', 'feature-control', 'datum', 'surface-finish', 'pitch-circle'])
    i = 'p%d' % len(ids)
    ids.append(i)
    decls = []
    if t in ('sketch', 'hidden'):
        decls.append('draw: %s;' % draw())
        for opt in ['revolve: x-axis;', 'mirror: x-axis;', 'mirror: y-axis;', 'thread: m8 1.25;', 'break: -5 5;']:
            if rnd.random() < 0.25:
                decls.append(opt)
    elif t == 'hole':
        decls.append('width: %d;' % rnd.choice([4, 8]))
        if rnd.random() < 0.4:
            decls.append(rnd.choice(['pattern: radial(6, 14);', 'pattern: grid(2, 2, 10, 10);', 'thread: 1.25;', 'thread: m6;']))
    elif t in ('rect', 'oval', 'box'):
        decls.append('width: %d; height: %d;' % (rnd.randint(10, 60), rnd.randint(10, 40)))
    elif t == 'plane':
        decls.append('at: 0;')
    lab = ' "%s"' % rnd.choice(['A', 'B', 'pos']) if rnd.random() < 0.4 else ''
    s = '|%s#%s|%s { %s }' % (t, i, lab, ' '.join(decls)) if decls else '|%s#%s|%s' % (t, i, lab)
    if depth < 2 and t in ('rect', 'sketch', 'box') and rnd.random() < 0.3:
        s += ' [ ' + '; '.join(part(depth + 1, ids) for _ in range(rnd.randint(1, 2))) + ' ]'
    return s

def drawing(ids, nested=False):
    t = rnd.choice(['drawing', 'drawing', 'floorplan'])
    decls = []
    if rnd.random() < 0.3:
        decls.append('unit: %s;' % rnd.choice(['mm', 'cm', 'm', 'in', 'px']))
    if rnd.random() < 0.2:
        decls.append('scale: 0.5;')
