    else:
        for _ in range(rnd.randint(1, 4)):
            body.append(part(0, ids))
        if len(ids) >= 2 and rnd.random() < 0.6:
            a, b = rnd.sample(ids, 2)
            body.append(rnd.choice(['%s:left (-) %s:right { side: bottom; }' % (a, b), '%s (o)' % a, '%s:top <- "note"' % a, '%s -> %s' % (a, b), 'zz -> %s' % a]))
    head = '|%s|%s' % (t, lab)
    if decls:
        head += ' { ' + ' '.join(decls) + ' }'
    return head + ' [\n  ' + '\n  '.join(body) + '\n]'

def gen():
