// the chain of the node enclosing the one being lowered
pub fn parent_is(&self, t: &str) -> bool {
    let k = self.stack.len();
    k >= 2 && self.stack[k - 2].chain.iter().any(|c| c == t)
}

fn dispatch(&mut self, n: &Node, o: ONode, chain: &[String], unit: Option<String>) -> R<ONode> {
    let is = |t: &str| chain.iter().any(|c| c == t);
    if is("topic") && !is("mindmap") {
        return Err(err("'|topic|' builds a tree — it belongs in a 'layout: tree'", n.span));
    }
    let mut tree_decls: Option<(bool, String)> = None;
    let mut hoisted = false;
    if let Some(explicit) = super::tree::container_kind(self, n) {
        let dir = if explicit {
            let d = n.style.iter().rev().find(|d| d.name == "direction").and_then(|d| d.first().map(|s| s.to_string()));
            super::tree::check_dir(d, n.span)?
        } else if let Some(d) = n.style.iter().rev().find(|d| d.name == "direction").and_then(|d| d.first().map(|s| s.to_string())) {
            // the container's own direction rules; the mindmap keeps its own
            super::tree::check_dir(Some(d), n.span)?
        } else if is("page") {
            super::page::page_dir(n)
        } else {
            hoisted = true;
            match super::tree::mindmap_dir(self, n.children.as_deref().unwrap_or(&[])) {
                Some((d, sp)) => super::tree::check_dir(Some(d), sp)?,
                None => "bilateral".to_string(),
            }
        };
        if explicit {
            super::tree::check_roots(n.children.as_deref().unwrap_or(&[]), n.span)?;
        }
        if !is("page") {
            tree_decls = Some((explicit, dir.clone()));
        } else {
            self.page_tree = Some((explicit, dir.clone()));
        }
        let mode = super::tree::TreeMode { mindmap: !explicit, dir, level: 0, side: None, hue: None, hoisted };
        if let Some(f) = self.stack.last_mut() {
            f.tree = Some(mode);
        }
    }
    let mut o = self.dispatch_family(n, o, chain, unit)?;
    if let Some((explicit, dir)) = tree_decls {
        // the drawing scale stays last
        let ppu = if o.decls.last().map_or(false, |d| d.name == "px-per-unit") { o.decls.pop() } else { None };
        super::tree::container_decls(&mut o.decls, explicit, &dir);
        o.decls.extend(ppu);
    }
    Ok(o)
}

fn dispatch_family(&mut self, n: &Node, mut o: ONode, chain: &[String], unit: Option<String>) -> R<ONode> {
    let is = |t: &str| chain.iter().any(|c| c == t);
    if is("page") {
        return super::page::page(self, n, o, chain);
    }
    // a schematic scope plans its wiring before its children lower
    let sch_layout = n.style.iter().rev().find(|d| d.name == "layout").and_then(|d| d.first().map(|s| s.to_string()))
        .or_else(|| {
            chain.iter().find_map(|t| {
                self.define(t).and_then(|d| d.decls.iter().rev().find(|d| d.name == "layout").and_then(|d| d.first().map(|s| s.to_string())))
            })
        });
    let explicit_sch = is("schematic") || sch_layout.as_deref() == Some("schematic");
    // a container inside a schematic wires the same way
    let inherited_sch = !explicit_sch
        && n.children.is_some()
        && (self.root_sch.is_some() || self.stack.iter().rev().skip(1).any(|f| f.sch.is_some()));
    if inherited_sch {
        let plan = self.sch_plan(n.children.as_deref().unwrap_or(&[]), false)?;
        if let Some(f) = self.stack.last_mut() {
            f.sch = Some(plan);
        }
    }
    if explicit_sch {
        if let Some(f) = self.stack.last_mut() {
            f.sch_explicit = true;
        }
        if !is("schematic") {
            // a scope of its own: the schematic spacing unless the type sets it
            let has = |name: &str| -> bool {
                n.style.iter().any(|d| d.name == name)
                    || chain.iter().any(|t| {
                        self.define(t).map_or(false, |d| d.decls.iter().any(|d| d.name == name))
                            || (t != "block"
                                && crate::types::find(t).map_or(false, |td| Decl::list(td.defaults).iter().any(|d| d.name == name)))
                    })
            };
            let mut pre = Vec::new();
            if !has("gap") {
                pre.push(Decl::val("gap", "100"));
            }
            if !has("clearance") {
                pre.push(Decl::val("clearance", "10"));
            }
            pre.extend(o.decls.drain(..));
            o.decls = pre;
        }
        let plan = self.sch_plan(n.children.as_deref().unwrap_or(&[]), true)?;
        if let Some(f) = self.stack.last_mut() {
            f.sch = Some(plan);
        }
    }
    if super::schematic::is_part(chain)
        || ["component", "pin", "space", "label", "junction"].iter().any(|t| is(t))
    {
        self.mark("junction");
    }
    if super::schematic::is_part(chain) {
        return super::schematic::part(self, n, o, chain);
    }
    if super::schematic::is_component(chain) {
        return super::schematic::component(self, n, o, chain);
    }
    if super::schematic::is_label(chain) {
        return super::schematic::label(self, n, o, chain);
    }
    if (is("drawing") || is("stack")) && self.in_labels == 0 {
        let px = super::sheet::px_per(unit.as_deref(), self.density, !is("drawing"));
        o.decls.retain(|d| d.name != "px-per-unit");
        o.decls.push(Decl::val("px-per-unit", &px));

