rnd = random.Random(seed)
d = '/tmp/desugar/tabfuzz'
os.makedirs(d, exist_ok=True)

def cellish():
    r = rnd.random()
    if r < 0.4:
        return '"%s"' % rnd.choice(['a', 'Name', 'x y', '1', ''])
    if r < 0.55:
        return '|cell| "%s"%s' % (rnd.choice(['c', 'D']), rnd.choice(['', ' { span: 2 1; }', ' { cell: 1 2; }', ' { align: end; }']))
    if r < 0.65:
        return '|header| "%s"' % rnd.choice(['H', 'Head'])
    if r < 0.72:
        return '|footer| "%s"' % rnd.choice(['F', 'total'])
    if r < 0.8:
        return '|box| "%s"' % rnd.choice(['b', 'B'])
    if r < 0.85:
        return '"%s" .k' % rnd.choice(['k', 'K'])
    if r < 0.9:
        return '|field| "%s"' % rnd.choice(['f'])
    return '"%s" { fill: red; }' % rnd.choice(['s'])

def table():
    t = rnd.choice(['table', 'table', 'entity', 'title-block', 'grid'])
