    lab = ' "%s"' % rnd.choice(['T', 'Users', '']) if rnd.random() < 0.6 else ''
    st = []
    if rnd.random() < 0.4:
        st.append('columns: %s;' % rnd.choice(['2', 'repeat(2)', '3', '80 1fr', 'auto auto auto']))
    if rnd.random() < 0.2:
        st.append('rows: %s;' % rnd.choice(['2', 'repeat(3)']))
    if t == 'title-block' and rnd.random() < 0.7:
        for k in rnd.sample(['title', 'number', 'revision', 'date', 'drawn', 'checked', 'scale', 'sheet', 'company', 'material'], rnd.randint(1, 4)):
            st.append('%s: "%s";' % (k, k.upper()))
    if rnd.random() < 0.15:
        st.append('align: %s;' % rnd.choice(['start', 'end', 'center']))
    if rnd.random() < 0.15:
        st.append('justify: %s;' % rnd.choice(['start', 'end']))
    s = '|%s%s|%s%s' % (t, idp, lab, (' { ' + ' '.join(st) + ' }') if st else '')
    if rnd.random() < 0.85:
