            lines.append('|page| { sheet: %s; } [\n%s\n]' % (rnd.choice(['a4', 'a3 landscape', 'a5']), table()))
        elif r < 0.25 and 'tbl' in ''.join(lines):
            lines.append('|tbl| "X" [ "a"; "b" ]')
        else:
            lines.append(table())
    return '\n'.join(lines) + '\n'

