import subprocess, os, random, difflib, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
n = int(sys.argv[2]) if len(sys.argv) > 2 else 200
show = int(sys.argv[3]) if len(sys.argv) > 3 else 3
rnd = random.Random(seed)
d = '/tmp/desugar/valfuzz'
os.makedirs(d, exist_ok=True)

def num():
    return rnd.choice(['0', '1', '2', '2.5', '3', '10', '12.75', '-1', '1e2', '0.333', '100', '297', '420', '1189', '50%', 'x', '"3"', '7.0', '1/3'])

def unit():
    return rnd.choice(['mm', 'cm', 'm', 'in', 'px'])

def item():
    r = rnd.random()
    if r < 0.12:
        return '|page| { %s }' % rnd.choice(['width: %s; height: %s;' % (num(), num()), 'sheet: %s;' % rnd.choice(['a4', 'a3 landscape', 'b', 'e portrait', 'a0']), 'unit: %s;' % unit(), ''])
    if r < 0.24:
        return '|drawing| { unit: %s; } [ |stairs| { steps: %s; } ]' % (unit(), num())
    if r < 0.36:
        return '|drawing| [ |hole| { thread: %s; %s } ]' % (num(), rnd.choice(['', 'pattern: radial(4);', 'pattern: grid(2, 2);', 'pattern: radial(%s);' % num()]))
    if r < 0.48:
        return '|drawing| { unit: %s; } [ |wall| { %s } ; |partition| ]' % (unit(), rnd.choice(['', 'thickness: %s;' % num()]))
    if r < 0.6:
        return '|stack| { unit: %s; } [ |box| ]' % unit()
    if r < 0.72:
        fields = rnd.sample(['title', 'number', 'revision', 'date', 'drawn', 'checked', 'scale', 'sheet', 'company', 'material'], rnd.randint(1, 5))
        st = ' '.join('%s: %s;' % (f, rnd.choice(['"V"', num(), 'word'])) for f in fields)
        if rnd.random() < 0.3:
            st += ' columns: %s;' % rnd.choice(['2', '4', 'repeat(2)', '80 1fr'])
        return '|page| [ |title-block| { %s } ]' % st
    if r < 0.84:
        return '|drawing| { of: %s; } [ |sketch| { draw: move(0, 0) right(%s); %s } ]' % (rnd.choice(['"view"', 'x', '1']), num(), rnd.choice(['', 'mirror: x-axis;', 'revolve: y-axis;', 'break: %s;' % num()]))
    return '|floorplan| { unit: %s; } [ |door| { width: %s; symbol: %s; } ; |window| ]' % (unit(), num(), rnd.choice(['single', 'double', 'sliding', 'x']))

def gen():
    lines = []
    if rnd.random() < 0.4:
        lines.append('{ density: %s; %s }' % (rnd.choice(['4', '2.5', '10', '3.7795']), rnd.choice(['', 'unit: %s;' % unit(), 'layout: drawing;', 'layout: floorplan;'])))
    for _ in range(rnd.randint(1, 3)):
        lines.append(item())
    return '\n'.join(lines) + '\n'

ok = 0
fails = []
for i in range(n):
    src = gen()
    p = os.path.join(d, 'g.lini')
    open(p, 'w').write(src)
    r1 = subprocess.run(['/workspace/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    r2 = subprocess.run(['/tmp/bin-desugar/executable', 'desugar', 'g.lini'], capture_output=True, cwd=d)
    if (r1.stdout, r1.stderr, r1.returncode) == (r2.stdout, r2.stderr, r2.returncode):
        ok += 1
    else:
        fails.append((src, r1, r2))
print('OK %d / %d' % (ok, n))
for src, r1, r2 in fails[:show]:
    print('=' * 30)
    print(src)
    a = (r1.stdout + r1.stderr).decode().splitlines()
    b = (r2.stdout + r2.stderr).decode().splitlines()
    for l in list(difflib.unified_diff(a, b, lineterm='', n=1))[2:40]:
        print(l)

