    let set = |name: &str| chain.iter().any(|t| cx.define(t).map_or(false, |d| d.decls.iter().any(|d| d.name == name)));
    if set("rotate") {
        o.decls.push(Decl::val("rotate", "0"));
    }
    if set("mirror") {
        o.decls.push(Decl::val("mirror", "none"));
    }
}

